/* @autogenerated */
import { TestBed } from '@angular/core/testing';
import { BehaviorSubject } from 'rxjs';
import { AppStateService } from '@shared/context/state/app-state.service';
import { UserInfo } from '@shared/context/identity/user-info.model';
import { grants, PermissionService } from './permission.service';

describe('PermissionService', () => {
  it('grants by role or permission only to authenticated users', () => {
    expect(grants({ authenticated: true, roles: ['admin'] }, 'admin')).toBeTrue();
    expect(grants({ authenticated: true, permissions: ['tenant:read'] }, 'tenant:read')).toBeTrue();
    expect(grants({ authenticated: true, roles: ['guest'] }, 'admin')).toBeFalse();
    expect(grants({ authenticated: false, roles: ['admin'] }, 'admin')).toBeFalse();
    expect(grants(null, 'admin')).toBeFalse();
  });

  it('has emits again only when the result changes', () => {
    const user$ = new BehaviorSubject<UserInfo>({ authenticated: false });
    TestBed.configureTestingModule({
      providers: [{ provide: AppStateService, useValue: { user$: () => user$ } }],
    });
    const values: boolean[] = [];

    TestBed.inject(PermissionService)
      .has('admin')
      .subscribe((v) => values.push(v));
    user$.next({ authenticated: true, roles: ['guest'] });
    user$.next({ authenticated: true, roles: ['admin'] });
    user$.next({ authenticated: true, roles: ['admin', 'guest'] });

    expect(values).toEqual([false, true]);
  });
});
